        },
        {
          id: 5,
          device: "会议室 PC",
          browser: "Edge · Windows",
          icon: "🖥️",
          passkey: "本机 Passkey",
          location: "公司",
          current: false,
          lastActive: "5 天前",
          hasPush: false,
        },
      ];

      let RECOVERY = [
        "7f3k-9d2x-qw8e",
        "m4p1-zt6v-bn3y",
        "h8q2-xc5j-rl9d",
        "k2w7-fg4m-ps6t",
        "n9v3-jh8q-wx2k",
        "b5t8-zm1p-df7h",
        "q6w2-kn9v-cx4j",
        "r3y7-pt5b-hg9m",
      ];

      function el(tag, attrs = {}, ...children) {
        const node = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs)) {
          if (k === "class") node.className = v;
          else if (k === "text") node.textContent = v;
          else if (k.startsWith("on"))
            node.addEventListener(k.slice(2).toLowerCase(), v);
          else node.setAttribute(k, v);
        }
        for (const c of children) {
          if (c == null) continue;
          node.append(c.nodeType ? c : document.createTextNode(c));
        }
        return node;
      }

      // ===== 渲染 Passkey =====
      function renderPasskeys() {
        const list = document.getElementById("passkey-list");
        document.getElementById("pk-count").textContent = PASSKEYS.length;
        list.replaceChildren(
          ...PASSKEYS.map((p) => {
            const removeBtn = el(
              "button",
              {
                class: "btn-danger rounded-lg px-3 py-1.5 text-xs",
                onclick: () => {
                  if (
                    confirm(
                      `确定删除 Passkey「${p.name}」吗？\n用它的设备将无法再登录（可用恢复码兜底）。`,
                    )
                  ) {
                    PASSKEYS = PASSKEYS.filter((x) => x.id !== p.id);
                    renderPasskeys();
                  }
                },
              },
              "删除",
            );
            return el(
              "div",
              { class: "card reveal visible p-5" },
              el(
                "div",
                { class: "flex flex-wrap items-center gap-4" },
                el("div", { class: "plat-icon", text: p.icon }),
                el(
                  "div",
                  { class: "min-w-0 flex-1" },
                  el(
                    "div",
                    { class: "flex flex-wrap items-center gap-2" },
                    el("span", {
                      class: "text-sm font-medium text-white",
                      text: p.name,
                    }),
                    el("span", {
                      class: "rounded-full px-2 py-0.5 text-[10px] font-medium",
                      style:
                        "background: rgba(139,139,253,0.12); color: var(--accent)",
                      text: p.type,
                    }),
                    p.current
                      ? el("span", {
                          class: "status-badge status-on",
                          text: "本机在用",
                        })
                      : null,
                  ),
                  el("div", {
                    class: "mt-1 text-xs text-zinc-500",
                    text: p.devices,
                  }),
                ),
                el(
                  "div",
                  { class: "flex flex-col items-end gap-1.5" },
                  el("div", {
                    class: "text-[11px] text-zinc-500",
                    text: `最近使用 ${p.lastUsed}`,
                  }),
                  el("div", {
                    class: "text-[10px] text-zinc-600",
                    text: `创建于 ${p.created}`,
                  }),
                ),
              ),
              el(
                "div",
                {
                  class:
                    "mt-4 flex items-center justify-end gap-2 border-t border-white/[0.05] pt-4",
                },
                p.current
                  ? el("span", {
                      class: "text-[11px] text-zinc-600",
                      text: "当前设备的凭证，不可删除",
                    })
                  : removeBtn,
              ),
            );
          }),
        );
      }
      renderPasskeys();

      // ===== 渲染会话 =====
      function renderSessions() {
        const list = document.getElementById("session-list");
        document.getElementById("session-count").textContent = SESSIONS.length;
        list.replaceChildren(
          ...SESSIONS.map((s) =>
            el(
              "div",
              { class: "flex flex-wrap items-center gap-4 px-5 py-4" },
              el("div", {
                class: "plat-icon !h-10 !w-10 text-xl",
                text: s.icon,
              }),
              el(
                "div",
                { class: "min-w-0 flex-1" },
                el(
                  "div",
                  { class: "flex flex-wrap items-center gap-2" },
                  el("span", {
                    class: "text-sm font-medium text-white",
                    text: s.device,
                  }),
                  s.current
                    ? el("span", {
                        class: "status-badge status-on",
                        text: "当前会话",
                      })
                    : null,
                  s.hasPush
                    ? el(
                        "span",
                        {
                          class:
                            "inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium",
                          style:
                            "background: rgba(52,211,153,0.1); color:#6ee7b7",
                          title: "这台设备已开启推送",
                        },
                        "🔔 接收通知",
                      )
                    : null,
                ),
                el(
                  "div",
                  {
                    class:
                      "mt-1 flex flex-wrap items-center gap-x-2 gap-y-0.5 text-xs text-zinc-500",
                  },
                  el("span", { text: s.browser }),
                  el("span", { class: "text-zinc-700", text: "·" }),
                  el("span", { text: s.location }),
                  el("span", { class: "text-zinc-700", text: "·" }),
                  el("span", {
                    text: s.current ? s.lastActive : `最后活跃 ${s.lastActive}`,
                  }),
                ),
              ),
              el(
                "div",
                { class: "flex items-center gap-3" },
                el("span", {
                  class: "hidden text-[11px] text-zinc-600 sm:block",
                  text: s.passkey,
                }),
                s.current
                  ? el("span", {
                      class: "text-[11px] text-zinc-600",
                      text: "—",
                    })
                  : el(
                      "button",
                      {
                        class: "btn-danger rounded-lg px-3 py-1.5 text-xs",
                        onclick: () => {
                          if (
                            confirm(
                              `吊销「${s.device}」的登录会话？该设备将需要重新登录。`,
                            )
                          ) {
                            SESSIONS = SESSIONS.filter((x) => x.id !== s.id);
                            renderSessions();
                          }
                        },
                      },
                      "吊销",
                    ),
              ),
            ),
          ),
        );
      }
      renderSessions();

      // ===== 恢复码 =====
      function mask(code) {
        return code.slice(0, 4) + "••••-••••";
      }
      function renderCodes() {
        const grid = document.getElementById("recovery-codes");
        grid.replaceChildren(
          ...RECOVERY.map((c) =>
            el("div", { class: "recovery-code", text: mask(c) }),
          ),
        );
        document.getElementById("codes-left").textContent = RECOVERY.length;
      }
      renderCodes();
      function regenCodes() {
        if (!confirm("重新生成会让旧恢复码全部失效，确定吗？")) return;
        const chars = "abcdefghjkmnpqrstuvwxyz23456789";
        const gen = () =>
          Array.from({ length: 3 }, () =>
            Array.from(
              { length: 4 },
              () => chars[Math.floor(Math.random() * chars.length)],
            ).join(""),
          ).join("-");
        RECOVERY = Array.from({ length: 8 }, gen);
        renderCodes();
        alert("已生成 8 个新恢复码（演示）。请立即保存。");
      }

      // 侧边栏（移动端）
      const sidebar = document.getElementById("sidebar");
      const overlay = document.getElementById("sidebar-overlay");
      document.getElementById("menu-btn").addEventListener("click", () => {
        sidebar.classList.remove("-translate-x-full");
        overlay.classList.remove("hidden");
      });
      overlay.addEventListener("click", () => {
        sidebar.classList.add("-translate-x-full");
        overlay.classList.add("hidden");
      });

      // 滚动渐入
      const io = new IntersectionObserver(
        (entries) =>
          entries.forEach(
            (e) => e.isIntersecting && e.target.classList.add("visible"),
          ),
        { threshold: 0.08 },
      );
      document.querySelectorAll(".reveal").forEach((el) => io.observe(el));
    </script>
  </body>
</html>

